def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', ''))
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transform_done'] = True
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(getv(ctx, 'world.inventory', ''))
    pc = getv(ctx, 'world.placed_count', nb.get('placed_count', 0))
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    if verb and target and act.startswith(verb + ' ') and target in act and 'nothing special' not in obs and 'cannot' not in obs:
        nb['transform_done'] = True
    if verb and target and act.startswith('put ') and target in act and dest and dest in act and 'you put' in obs:
        nb['transform_done'] = True
    holding = bool(target and target in inv and 'not carrying' not in inv and 'nothing' not in inv)
    wrong = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and target and target not in inv)
    adm = [text(a) for a in (ctx.get('admissible') or [])]
    take_here = bool(target and any(a.startswith('take ') and target in a for a in adm))
    put_here = bool(target and dest and any(a.startswith('put ') and target in a and dest in a for a in adm))
    trans_here = bool(verb and target and any(a.startswith(verb + ' ') and target in a for a in adm))
    if wrong:
        stage = 'wrong_inventory'
    elif holding and verb and not nb.get('transform_done'):
        stage = 'transform'
    elif holding and dest and not put_here:
        stage = 'go_destination'
    elif holding and dest and put_here:
        stage = 'put_target'
    elif target and take_here:
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['transform_verb'] = verb
    return None

