def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or 'target object'
    dest = nb.get('destination_type') or 'destination'
    verb = nb.get('transform_verb') or needverb(nb.get('task_type', ''))
    tt = nb.get('task_type', '')
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target item. Do not place it as the goal; recover by setting it aside only if needed, then find the ' + target + '.'
    elif stage == 'transform' and verb:
        msg = 'You are carrying the ' + target + '. Use the ' + verb + ' action with the proper appliance before any put action; do not substitute the opposite transform.'
    elif stage == 'go_destination' and dest:
        msg = 'Carry the ' + target + ' to a ' + dest + ' and use the put action there; other receptacles are not the goal destination.'
    elif stage == 'put_target' and dest:
        msg = 'You are at a ' + dest + ' with the ' + target + '. Use the put action now instead of examining, opening, or moving away.'
    elif stage == 'take_target':
        msg = 'A ' + target + ' is available here. Take it before continuing to search other places.'
    elif stage == 'find_target' and 'two' in tt and nb.get('placed_count', 0) > 0:
        msg = 'One ' + target + ' is already placed. Leave it there, find another ' + target + ', and use the same ' + dest + ' destination.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

